Method.Implementation:
	$$$TRACE("Inside Operation SHSPEDISEGMENTINSERT")
	#dim Payload as %Stream.GlobalCharacter
	Set stream=req.Payload
	Do stream.Rewind()
	$$$TRACE("Payload Stream size:"_stream.Size)
	Set EdiCheckNo=req.EdiCheckNo
	$$$TRACE("EdiCheckNo:"_EdiCheckNo)

	set sepStr = ""
 	set SegCount = 0

 	if (stream.Size < 110)
 	{
	 	set tSC = $$$ERROR("X12 message has no segments")
	 	Quit tSC
	}
 	else
	{
		// Get separators
		set Payload = stream.Read(110,.sc) 
	 	S fieldDelim=$E(Payload,104)
	 	$$$TRACE("fieldDelim:"_fieldDelim)
	 	S segDelim=$E(Payload,106)
	 	$$$TRACE( "segDelim:"_segDelim)
	}
	DO stream.Rewind()


 	#dim tSC As %Status=$$$OK
	#dim tRTs As %ListOfObjects
	#dim tResultSet,snap As EnsLib.SQL.Snapshot
	#dim debug As %Boolean=0
	set debug=$g(^IHCDebugCode(..%ConfigName),0)
	Set snap=##class(EnsLib.SQL.Snapshot).%New()
	Set snap.MaxRowsToGet=-1
	Set tRTs=##class(%Library.ListOfObjects).%New()
	Do tRTs.Insert(snap)

	$$$TRACE("Inside "_..%ConfigName_" Method SHSP_EDI_SEGMENT_INSERT")
	S strTokenDelim=""
	// Read stream
 	try
 	{
		While 'stream.AtEnd 
 		{ 
   			set rl = stream.Read(100,.tSC) 
   			If $$$ISERR(tSC) 
   			{ 
      			$$$LOGERROR("ERROR in reading stream: " _ tSC)
      			Quit
  			} 
  			else
   			{
			   	$$$TRACE("Read # of bytes from stream: " _ $L(rl))
	   			Set SegCounts = $L(rl,segDelim) 
	   			if SegCounts = 1 
	   			{
		   			// SegDelimitor not found
		   			set sepStr = sepStr _ rl
	   			}
	   			else
	   			{
		   			set sepStr = sepStr _ rl


		   			For i=1:1:(SegCounts-1)
	   				{
			   			// Found Segment delimiter, create the string till that character
			   			set SegCount = SegCount + 1

			   			Set strTokenDelim = $P(sepStr, segDelim, i)
			   			$$$TRACE("SegCount: " _ SegCount)
						$$$TRACE("Single segment through loop:"_strTokenDelim)
						Set ioParms=5
						Set ioParms(1)=EdiCheckNo
						Set ioParms(1,"SqlType")=4
						Set ioParms(2)=strTokenDelim_"~"
						//$$$TRACE("ioParms(2) before setting sqlType"_ioParms(2))
						Set ioParms(2,"SqlType")=12
						//$$$TRACE("ioParms(2) After setting sqlType"_ioParms(2))
						Set ioParms(3)=fieldDelim
						Set ioParms(3,"SqlType")=12
						Set ioParms(4,"SqlType")=4
						Set ioParms(5,"SqlType")=12
						$$$TRACE("calling getSHSP_EDI_SEGMENT_INSERT For "_i_"th segment: " _ ioParms(1) _", " _ ioParms(2) _", " _ ioParms(3))

						Set tQuery="{call EDI_CORE.SHSP_EDI_SEGMENT_INSERT(?,?,?,?,?)}"

		 	  			Set tSC = ..Adapter.ExecuteProcedureParmArray(.tRTs,.tOutParms,tQuery,"iiioo#",.ioParms)

						if $$$ISOK(tSC)
						{
							If $ISOBJECT(tOutParms)
				 			{
			 					$$$TRACE("outparm cnt  :"_tOutParms.Count())
			  					$$$TRACE(tOutParms.Size_" || Error code: "_tOutParms.GetAt(1)_" || Error desc:  "_tOutParms.GetAt(2)) 
			    				Set PErrorcode = tOutParms.GetAt(1)
			  					Set PErrorDescription = tOutParms.GetAt(2)
			    				$$$TRACE("PErrorcode : "_PErrorcode)
			  					$$$TRACE("PErrorDescription : "_PErrorDescription)
				    			If PErrorcode '= "0"
				    			{
				    				set tSC = $$$ERROR("Received error when calling stored procedure with segment_"_strTokenDelim_"ErrorCode:"_PErrorcode_"ErrorDescription:"_PErrorDescription)
				    			}
							}
		    				Else
		    				{
								set tSC = $$$ERROR("Exception on getting response from StoredProcedure call, " _ tSC)
	        				}
		  	        	}
	   				}
	  	        	// Create next segment from remaining characters in the string
		   			set sepStr = $P(sepStr, segDelim, i+1)

	  			}
	  		}
   			If stream.AtEnd  { $$$TRACE("END of Stream: " _ sepStr) } 
  		}

 	}

 	//try end
 	Catch e{
	 	Set errTxt = "Exception in inserting data into oracle DB"
	 	do ..ItfSendEmailOnError("Unable to send X12 message to SelectHealth Oracle database",e)
	 	set tSC = $$$ERROR("Exception in insert data into  Oracle DB: " _errTxt)
	 }
 	Quit tSC
 	//}

$$$TRACE("Inside Process27xMessage Operation")
set stat = $$$OK
set req = ##class(IHC.ITF.Request.ShVariousX12TransTrackELIGIBILITYCLAIMSTAT.SHSPEDITRANSACTIONINSERT).%New()
set req.pSBSBID = pReq.pSBSBID
set req.pTransactionFileName = pReq.pTransactionFileName
set req.TtMsgType = pReq.TtMsgType
set req.TimeStamp = pReq.TimeStamp
set req.strTtBatchReal = pReq.strTtBatchReal
set req.TtUniqueId = pReq.TtUniqueId


#dim pResp As Ens.StringContainer
set stat = ..SHSPEDITRANSACTIONINSERT(req, .pResp)
$$$TRACE(req.TtMsgType _ " SHSPEDITRANSACTIONINSERT status: " _ stat )
if ( ($$$ISOK(stat)) && ($ISOBJECT(pResp)))
{ 
	$$$TRACE(pResp.StringValue _ ", Check # " _ $E(pResp.StringValue, 1, $F(pResp.StringValue, "|") - 2))
	set segReq = ##class(IHC.ITF.Request.ShVariousX12TransTrackELIGIBILITYCLAIMSTAT.SHSPEDISEGMENTINSERT).%New()
	#dim payload as %Stream.GlobalCharacter
	set payload = ##class(%Stream.GlobalCharacter).%New()
	Do payload.Write(pReq.Payload)
	set segReq.Payload = payload
	set segReq.EdiCheckNo = $PIECE(pResp.StringValue,"|",1) 
	set stat = ..SHSPEDISEGMENTINSERT(segReq, .pResp)
	$$$TRACE(req.TtMsgType _ " SHSPEDISEGMENTINSERT status: " _ stat )
	if ( $$$ISOK(stat))
	{
		$$$TRACE("String: " _ pResp.StringValue)
	}
}
set charSep = $E(pReq.RespPayload, 4)
set msgType271 = "ST" _ charSep _ "271" _ charSep
set msgType277 = "ST" _ charSep _ "277" _ charSep
set ta1MsgType = "TA1" _ charSep
set ackMsgType =	"ST" _ charSep _ "999" _ charSep
if (pReq.RespPayload [ msgType271)
{
	set req.TtMsgType = "271"
}
elseif (pReq.RespPayload [ msgType277)
{
	set req.TtMsgType = "277"
}
elseif (pReq.RespPayload [ ackMsgType)
{
	set req.TtMsgType = "999"
}
elseif (pReq.RespPayload [ ta1MsgType)
{
	set req.TtMsgType = "TA1"
}	
else
{
	$$$TRACE("Did not find: " _ msgType271 _ " / " _ msgType277 _ " in " _ $E(pReq.RespPayload, 1, 6))
	set req.TtMsgType = "ERR"
}

set req.TimeStamp = pReq.RespTimeStamp

set stat = ..SHSPEDITRANSACTIONINSERT(req, .pResp)
$$$TRACE(req.TtMsgType _" SHSPEDITRANSACTIONINSERT status: " _ stat )
if ( ($$$ISOK(stat)) && ($ISOBJECT(pResp)))
{ 
	$$$TRACE(pResp.StringValue _ ", Check # " _ $E(pResp.StringValue, 1, $F(pResp.StringValue, "|") - 2))
	set segReq = ##class(IHC.ITF.Request.ShVariousX12TransTrackELIGIBILITYCLAIMSTAT.SHSPEDISEGMENTINSERT).%New()
	set payload = ##class(%Stream.GlobalCharacter).%New()
	Do payload.Write(pReq.RespPayload)
	set segReq.Payload = payload
	set segReq.EdiCheckNo = $PIECE(pResp.StringValue,"|",1) 
	set stat = ..SHSPEDISEGMENTINSERT(segReq, .pResp)
	$$$TRACE(req.TtMsgType _ " SHSPEDISEGMENTINSERT status: " _ stat )
	if ( $$$ISOK(stat))
	{
		$$$TRACE("String: " _ pResp.StringValue)
	}
}



Quit stat
